#!/usr/bin/env python3
"""New, standalone P3 ModuleData witness driver; never a cache-adoption driver.

Execute this file on P3 with Python 3.  It contains the exact reviewed Lean
witness and immutable binding manifests.  All writes are confined to one new
0700 directory under /workspace/p15-cache-evidence.  No Lake command, project
import, project compilation, cache rewrite, Git mutation, or network operation
is performed.  The first failed gate ends the run; partial evidence is retained.
"""

from __future__ import annotations

import base64
import ctypes
import gzip
import hashlib
import json
import os
from pathlib import Path
import re
import select
import shutil
import stat
import struct
import subprocess
import sys
import tempfile
import time
import traceback


SCRIPT_SHA256 = "6397b5690ae3cdf1aab169bfbc076fd576c93720ae9bec74c81136f2f9773385"
REVIEW_SHA256 = "0ce90d47de5a69774f0aaa030fd464db4002a031496c045b04a73c6d1bbca380"
REUSE_SHA256 = "1aab54f7655ca68ae24294d49eff3c1f08455d3c31982c78d1e017888bc1316b"
SCRIPT_GZIP_BASE64 = ""
REVIEW_GZIP_BASE64 = ""
REUSE_GZIP_BASE64 = ""

PROJECT = Path("/workspace/goldbach-p3")
LEAN = Path("/workspace/toolchains/lean-4.33.0-rc1-linux/bin/lean")
EVIDENCE_PARENT = Path("/workspace/p15-cache-evidence")
BASELINE_RECEIPT = PROJECT / ".lake/p3-fourth-verification/report.json"
PACKAGE_KEY = "_private.Lean.Compiler.ModPkgExt.0.Lean.modPkgExt"
PAIR_TIMEOUT_SECONDS = 300
CHUNK_BYTES = 4 * 1024 * 1024
ALLOWED_MODULES = [
    "ImbalancedChen.Part3OffDiagonalModuli",
    "ImbalancedChen.Part3OriginalDyadicChartPartition",
    "ImbalancedChen.Part3PrimeProductChartTransfer",
    "ImbalancedChen.Part3PrimeProductVonMangoldt",
    "ImbalancedChen.Part3ProperPrimePowerCount",
]
LONG_SLOT_MODULE = "ImbalancedChen.Part3LongSlotDistribution"
LONG_SLOT_SOURCE_SHA256 = "67ccc48e6a4befadfd4b5639e2cdb4bd43e443b8f4eaf3086fe5a6c5fbd0023e"
LONG_SLOT_ACCEPTED_SHA256 = "fd8cdcf5ac894e5b904f8bdc0e80506b16c23bb17bc1a568ea4a3a5b50b61816"
OUTPUT_ROOT: Path | None = None


class Hold(RuntimeError):
    def __init__(self, code: str, detail: str = "") -> None:
        super().__init__(detail or code)
        self.code = code


def need(condition: bool, code: str, detail: str = "") -> None:
    if not condition:
        raise Hold(code, detail)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def utc_now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def stat_token(value: os.stat_result) -> tuple[int, int, int, int, int]:
    # Access time is deliberately excluded: this driver only reads the inputs.
    return value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, value.st_mode


def fingerprint(path: Path, optional: bool = False) -> dict:
    path = Path(path)
    if not os.path.lexists(path):
        need(optional, "MISSING_REQUIRED_FILE", str(path))
        return {"path": str(path), "exists": False}
    before = path.stat()
    need(stat.S_ISREG(before.st_mode), "NOT_A_REGULAR_INPUT_FILE", str(path))
    digest = hashlib.sha256()
    size = 0
    with path.open("rb") as stream:
        while True:
            chunk = stream.read(CHUNK_BYTES)
            if not chunk:
                break
            digest.update(chunk)
            size += len(chunk)
    after = path.stat()
    need(stat_token(before) == stat_token(after), "FILE_CHANGED_DURING_HASH", str(path))
    need(size == after.st_size, "FILE_SIZE_CHANGED_DURING_HASH", str(path))
    return {
        "path": str(path),
        "realpath": str(path.resolve(strict=True)),
        "exists": True,
        "bytes": size,
        "sha256": digest.hexdigest(),
        "stat": list(stat_token(after)),
        "symlink_target": os.readlink(path) if path.is_symlink() else None,
    }


def require_pin(path: Path, pin: dict) -> dict:
    actual = fingerprint(path)
    need(actual["sha256"] == pin["sha256"], "PINNED_SHA256_MISMATCH", str(path))
    if "bytes" in pin:
        need(actual["bytes"] == pin["bytes"], "PINNED_SIZE_MISMATCH", str(path))
    return actual


def assert_output_path(path: Path) -> None:
    need(OUTPUT_ROOT is not None, "OUTPUT_ROOT_NOT_INITIALIZED")
    assert OUTPUT_ROOT is not None
    need(path.is_absolute(), "OUTPUT_PATH_NOT_ABSOLUTE", str(path))
    need(path.parent.resolve(strict=True).is_relative_to(OUTPUT_ROOT),
         "WRITE_OUTSIDE_FRESH_EVIDENCE_ROOT", str(path))


def write_new(path: Path, data: bytes) -> None:
    assert_output_path(path)
    descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    with os.fdopen(descriptor, "wb") as stream:
        stream.write(data)


def write_json(path: Path, value: object) -> None:
    write_new(path, (json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode())


def private_mkdir(path: Path) -> None:
    assert_output_path(path)
    path.mkdir(mode=0o700)


def emit(value: dict) -> None:
    # Only callers' bounded, deliberately selected metadata is sent to stdout.
    text = json.dumps(value, sort_keys=True, separators=(",", ":"))
    need(len(text.encode()) <= 4096, "PUBLIC_STATUS_TOO_LARGE")
    print(text, flush=True)


def bytes_equal(left: Path, right: Path) -> bool:
    if left.stat().st_size != right.stat().st_size:
        return False
    with left.open("rb") as a, right.open("rb") as b:
        while True:
            x, y = a.read(CHUNK_BYTES), b.read(CHUNK_BYTES)
            if x != y:
                return False
            if not x:
                return True


def decode_pinned(encoded: str, expected: str) -> bytes:
    data = gzip.decompress(base64.b64decode(encoded, validate=True))
    need(sha256_bytes(data) == expected, "EMBEDDED_PAYLOAD_HASH_MISMATCH")
    return data


def load_embedded() -> tuple[bytes, bytes, bytes, dict, dict]:
    script = decode_pinned(SCRIPT_GZIP_BASE64, SCRIPT_SHA256)
    review_raw = decode_pinned(REVIEW_GZIP_BASE64, REVIEW_SHA256)
    reuse_raw = decode_pinned(REUSE_GZIP_BASE64, REUSE_SHA256)
    review, reuse = json.loads(review_raw), json.loads(reuse_raw)
    need(review["script"]["sha256"] == SCRIPT_SHA256 and review["script"]["bytes"] == len(script),
         "REVIEW_SCRIPT_BINDING_MISMATCH")
    need(review["immutable_reuse_manifest"]["sha256"] == REUSE_SHA256,
         "IMMUTABLE_REUSE_BINDING_MISMATCH")
    need([p["module"] for p in review["pairs"]] == ALLOWED_MODULES, "PAIR_SET_CHANGED")
    closure = reuse["project_import_closure"]
    need(len(closure) == 77 and len({p["module"] for p in closure}) == 77,
         "SOURCE_CLOSURE_IS_NOT_EXACTLY_77")
    by_module = {p["module"]: p for p in closure}
    for item in closure:
        need(set(item["project_imports"]).issubset(by_module), "SOURCE_GRAPH_NOT_CLOSED", item["module"])
        rel = Path(item["path"])
        need(not rel.is_absolute() and ".." not in rel.parts and rel.parts[0] == "ImbalancedChen",
             "UNEXPECTED_SOURCE_PATH", str(rel))
    bindings = {p["module"]: p["object_reuse_binding"] for p in reuse["canonical_additions"]}
    for pair in review["pairs"]:
        module, stem = pair["module"], pair["module"].replace(".", "/")
        source = by_module[module]
        binding = bindings[module]
        need(pair["source_path"] == str(PROJECT / source["path"]), "PAIR_SOURCE_PATH_MISMATCH", module)
        need(pair["source_sha256"] == source["sha256"], "PAIR_SOURCE_BINDING_MISMATCH", module)
        need(pair["current"]["path"] == str(PROJECT / ".lake/build/lib/lean" / (stem + ".olean")),
             "PAIR_CURRENT_PATH_MISMATCH", module)
        need(pair["accepted"]["path"] == binding["historical_object_path"],
             "PAIR_ACCEPTED_PATH_MISMATCH", module)
        need(pair["accepted"]["sha256"] == binding["expected_olean_sha256"] ==
             pair["expected_accepted_sha256_from_immutable_reuse_manifest"],
             "PAIR_ACCEPTED_RECEIPT_BINDING_MISMATCH", module)
        need(binding["receipt_key"] == "baseline" and binding["source_hash_matches_selected_source"],
             "PAIR_BASELINE_BINDING_MISMATCH", module)
        need(pair["real_trace"]["path"] == str(Path(pair["current"]["path"]).with_suffix(".trace")),
             "PAIR_TRACE_PATH_MISMATCH", module)
    need(by_module[LONG_SLOT_MODULE]["sha256"] == LONG_SLOT_SOURCE_SHA256,
         "LONG_SLOT_SOURCE_BINDING_MISMATCH")
    need(reuse["acceptance_receipts"]["baseline"]["recorded_cloud_report_path"] == str(BASELINE_RECEIPT),
         "BASELINE_RECEIPT_PATH_MISMATCH")
    return script, review_raw, reuse_raw, review, reuse


def require_no_parts(pair: dict) -> None:
    for key in ("current", "accepted"):
        base = pair[key]["path"]
        for suffix in (".server", ".private"):
            need(not os.path.lexists(base + suffix), "UNEXPECTED_MODULE_PART", base + suffix)


def source_state(reuse: dict) -> dict:
    sources = {}
    for item in reuse["project_import_closure"]:
        path = PROJECT / item["path"]
        need(path.resolve(strict=True).is_relative_to(PROJECT), "SOURCE_ESCAPES_PROJECT", str(path))
        sources[item["module"]] = require_pin(path, item)
    configs = {item["path"]: require_pin(PROJECT / item["path"], item) for item in reuse["configuration"]}
    receipt = require_pin(BASELINE_RECEIPT, reuse["acceptance_receipts"]["baseline"]["git"])
    return {"sources": sources, "configuration": configs, "baseline_receipt": receipt}


def pair_input_state(pair: dict) -> dict:
    require_no_parts(pair)
    result = {"source": require_pin(Path(pair["source_path"]), {"sha256": pair["source_sha256"]})}
    result.update({key: require_pin(Path(pair[key]["path"]), pair[key])
                   for key in ("current", "accepted", "real_trace")})
    trace = json.loads(Path(pair["real_trace"]["path"]).read_bytes())
    expected = pair["real_trace"]
    need(trace.get("schemaVersion") == expected["schemaVersion"] and trace.get("synthetic") is False,
         "TRACE_SCHEMA_OR_SYNTHETIC_MISMATCH", pair["module"])
    need(trace.get("outputs") == expected["observed_outputs"] and trace.get("depHash") == expected["observed_depHash"],
         "TRACE_FULL_OUTPUT_OR_DEPHASH_MISMATCH", pair["module"])
    return result


def native_bundle(module: str) -> dict:
    stem = Path(module.replace(".", "/"))
    files = set()
    roots = [PROJECT / ".lake/build/lib/lean", PROJECT / ".lake/build/ir", PROJECT / ".lake/build/lib"]
    for root in roots:
        parent = (root / stem).parent
        if parent.is_dir():
            files.update(p for p in parent.glob(stem.name + ".*") if p.is_file() or p.is_symlink())
    # Include absent keys to catch a part or sidecar appearing during the witness.
    for suffix in (".olean", ".olean.server", ".olean.private", ".ilean", ".trace",
                   ".olean.hash", ".olean.server.hash", ".olean.private.hash", ".ilean.hash"):
        files.add(PROJECT / ".lake/build/lib/lean" / (str(stem) + suffix))
    return {str(p): fingerprint(p, optional=True) for p in sorted(files)}


def long_slot_metadata() -> dict:
    stem = LONG_SLOT_MODULE.replace(".", "/")
    normal = PROJECT / ".lake/build/lib/lean" / stem
    overlay = PROJECT / ".lake/p3-fourth-verification/objects" / (stem + ".olean")
    row = {
        "module": LONG_SLOT_MODULE,
        "scope": "READ_ONLY_METADATA_ONLY_NO_SIXTH_EQUIVALENCE_CHECK",
        "expected_accepted_olean_sha256": LONG_SLOT_ACCEPTED_SHA256,
        "source": require_pin(PROJECT / (stem + ".lean"), {"sha256": LONG_SLOT_SOURCE_SHA256}),
        "current": {suffix: fingerprint(Path(str(normal) + suffix), optional=True)
                    for suffix in (".olean", ".trace", ".olean.private", ".olean.server")},
        "accepted_overlay": fingerprint(overlay, optional=True),
    }
    row["accepted_overlay_matches_expected_if_present"] = (
        row["accepted_overlay"].get("sha256") == LONG_SLOT_ACCEPTED_SHA256
        if row["accepted_overlay"]["exists"] else None)
    return row


def clean_environment(temp_dir: Path) -> dict[str, str]:
    env = os.environ.copy()
    for key in ("LEAN_PATH", "LEAN_SRC_PATH", "LEAN_SYSROOT", "LD_PRELOAD", "LD_AUDIT",
                "LD_LIBRARY_PATH", "LD_DEBUG", "LD_DEBUG_OUTPUT"):
        env.pop(key, None)
    env.update({"LC_ALL": "C", "TMPDIR": str(temp_dir), "PYTHONDONTWRITEBYTECODE": "1"})
    return env


def is_tooling_file(path: Path) -> bool:
    name = path.name
    return (name.endswith((".olean", ".olean.server", ".olean.private", ".ilean", ".ir", ".ir.sig"))
            or ".so" in name)


def tooling_fingerprints(prefix: Path) -> dict:
    result = {}
    for path in sorted((prefix / "lib").rglob("*")):
        if path.is_file() and is_tooling_file(path):
            real = path.resolve(strict=True)
            if str(real) not in result:
                result[str(real)] = fingerprint(real)
    need(bool(result), "NO_CORE_TOOLING_FILES")
    for rel in ("Lean.olean", "Lean/Compiler/ModPkgExt.olean", "Lake/Build/Trace.olean"):
        need(str((prefix / "lib/lean" / rel).resolve(strict=True)) in result,
             "MISSING_REQUIRED_CORE_MODULE", rel)
    return result


def library_dependencies(prefix: Path, runtime: dict, env: dict, root: Path) -> dict:
    ldd = shutil.which("ldd", path=env.get("PATH"))
    need(ldd is not None, "LDD_NOT_AVAILABLE")
    targets = [LEAN.resolve(strict=True)]
    # Query the executable and actual core/Lake shared libraries, not compiler
    # linker scripts such as lib/libc++.so or glibc compatibility stubs.  The
    # complete public tooling inventory remains fingerprinted separately.
    core_library_root = (prefix / "lib/lean").resolve(strict=True)
    targets.extend(Path(p) for p in runtime
                   if ".so" in Path(p).name and Path(p).parent == core_library_root)
    # The retained first run mapped /etc/ld.so.cache. Bind this loader input
    # before ldd and Lean, retaining all mapped-file and final equality checks.
    loader_cache = Path("/etc/ld.so.cache").resolve(strict=True)
    dependencies = {str(loader_cache): fingerprint(loader_cache)}
    records = []
    for index, target in enumerate(targets):
        with target.open("rb") as stream:
            need(stream.read(4) == b"\x7fELF", "LDD_CORE_TARGET_NOT_ELF", str(target))
        proc = subprocess.run([ldd, str(target)], cwd=root, env=env, stdout=subprocess.PIPE,
                              stderr=subprocess.PIPE, check=False, timeout=30)
        write_new(root / f"ldd-{index:02d}.stdout", proc.stdout)
        write_new(root / f"ldd-{index:02d}.stderr", proc.stderr)
        need(proc.returncode == 0 and b"not found" not in proc.stdout,
             "LDD_DEPENDENCY_FAILURE", str(target))
        text = proc.stdout.decode("utf-8", errors="strict")
        paths = []
        for line in text.splitlines():
            match = re.search(r"=>\s+(/\S+)", line) or re.match(r"\s*(/\S+)", line)
            if match:
                path = Path(match.group(1)).resolve(strict=True)
                paths.append(str(path))
                if str(path) not in dependencies:
                    dependencies[str(path)] = fingerprint(path)
        records.append({"target": str(target), "exit_code": proc.returncode, "dependencies": paths})
    write_json(root / "ldd-records.json", records)
    need(any("libc.so" in Path(p).name for p in dependencies), "NO_LIBC_DEPENDENCY_CAPTURED")
    return dependencies


class CoreOpenObserver:
    """Linux inotify captures core-file opens; the maps log is process-specific.

    Inotify events can include concurrent readers, so its list is explicitly a
    superset.  Every possible core input is already SHA-bound in runtime_before.
    Any mutation or queue overflow aborts the witness rather than weakening it.
    """

    IN_OPEN = 0x20
    BAD = 0x00000002 | 0x00000004 | 0x00000008 | 0x00000040 | 0x00000080 | 0x00000100 | 0x00000200 | 0x00000400 | 0x00000800
    OVERFLOW = 0x00004000

    def __init__(self, prefix: Path) -> None:
        libc = ctypes.CDLL(None, use_errno=True)
        init = libc.inotify_init1
        init.argtypes, init.restype = [ctypes.c_int], ctypes.c_int
        add = libc.inotify_add_watch
        add.argtypes, add.restype = [ctypes.c_int, ctypes.c_char_p, ctypes.c_uint32], ctypes.c_int
        self.fd = init(os.O_NONBLOCK | os.O_CLOEXEC)
        need(self.fd >= 0, "INOTIFY_INIT_FAILED", str(ctypes.get_errno()))
        self.directories = {}
        self.opened = set()
        self.bad_events = []
        try:
            directories = [prefix / "lib"] + [p for p in (prefix / "lib").rglob("*") if p.is_dir()]
            for path in directories:
                wd = add(self.fd, os.fsencode(path), self.IN_OPEN | self.BAD)
                need(wd >= 0, "INOTIFY_WATCH_FAILED", str(path))
                self.directories[wd] = path
        except BaseException:
            self.close()
            raise

    def drain(self) -> None:
        while True:
            try:
                data = os.read(self.fd, 1024 * 1024)
            except BlockingIOError:
                return
            if not data:
                return
            offset = 0
            while offset < len(data):
                wd, mask, cookie, length = struct.unpack_from("iIII", data, offset)
                name = os.fsdecode(data[offset + 16:offset + 16 + length].split(b"\0", 1)[0])
                offset += 16 + length
                if mask & self.OVERFLOW:
                    raise Hold("CORE_OPEN_OBSERVER_OVERFLOW")
                parent = self.directories.get(wd)
                if parent is None:
                    continue
                path = parent / name if name else parent
                if mask & self.BAD:
                    self.bad_events.append({"path": str(path), "mask": mask})
                if mask & self.IN_OPEN and not mask & 0x40000000:
                    self.opened.add(str(path.resolve(strict=True)))

    def close(self) -> None:
        if self.fd >= 0:
            os.close(self.fd)
            self.fd = -1


def run_witness(pair: dict, script: Path, evidence: Path, logs: Path,
                prefix: Path, env: dict, runtime: dict, system_libraries: dict) -> dict:
    need(not os.path.lexists(evidence), "PAIR_OUTPUT_ALREADY_EXISTS")
    argv = [str(LEAN), "-DwarningAsError=true", "--run", str(script), pair["module"],
            pair["current"]["path"], pair["accepted"]["path"], str(evidence)]
    run_env = env.copy()
    run_env.update({"LD_DEBUG": "libs,files", "LD_DEBUG_OUTPUT": str(logs / "loader")})
    stdout_path, stderr_path = logs / "stdout", logs / "stderr"
    maps_path = logs / "process-maps.jsonl"
    observer = CoreOpenObserver(prefix)
    process = None
    mapped_files = set()
    started = time.monotonic()
    result = {"argv": argv, "cwd": str(OUTPUT_ROOT), "started_at": utc_now(),
              "timeout_seconds": PAIR_TIMEOUT_SECONDS, "env_removed": ["LEAN_PATH", "LEAN_SRC_PATH", "LEAN_SYSROOT", "LD_PRELOAD", "LD_AUDIT", "LD_LIBRARY_PATH"],
              "env_set": {"LC_ALL": "C", "TMPDIR": env["TMPDIR"], "LD_DEBUG": "libs,files"}}
    try:
        with stdout_path.open("xb") as stdout, stderr_path.open("xb") as stderr, maps_path.open("x") as maps:
            process = subprocess.Popen(argv, cwd=OUTPUT_ROOT, env=run_env, stdout=stdout,
                                       stderr=stderr, stdin=subprocess.DEVNULL, close_fds=True)
            last_maps = None
            while True:
                observer.drain()
                try:
                    raw_maps = Path(f"/proc/{process.pid}/maps").read_text()
                except FileNotFoundError:
                    raw_maps = ""
                if raw_maps and raw_maps != last_maps:
                    maps.write(json.dumps({"elapsed_seconds": time.monotonic() - started,
                                           "maps": raw_maps}) + "\n")
                    last_maps = raw_maps
                    for line in raw_maps.splitlines():
                        fields = line.split(None, 5)
                        if len(fields) == 6 and fields[5].startswith("/"):
                            need(not fields[5].endswith(" (deleted)"), "MAPPED_FILE_DELETED_DURING_RUN")
                            mapped_files.add(str(Path(fields[5]).resolve(strict=True)))
                if process.poll() is not None:
                    break
                need(time.monotonic() - started <= PAIR_TIMEOUT_SECONDS, "PAIR_TIMEOUT")
                select.select([observer.fd], [], [], 0.05)
            observer.drain()
            result["exit_code"] = process.wait()
    finally:
        if process is not None and process.poll() is None:
            process.kill()
            result["exit_code"] = process.wait()
        result.update({"ended_at": utc_now(), "elapsed_seconds": time.monotonic() - started,
                       "observed_core_open_paths_superset": sorted(observer.opened),
                       "core_mutation_events": observer.bad_events,
                       "process_mapped_files": sorted(mapped_files)})
        observer.close()
        write_json(logs / "run.json", result)
    need(result["exit_code"] == 0, "LEAN_WITNESS_NONZERO_EXIT", pair["module"])
    need(not result["core_mutation_events"], "CORE_RUNTIME_MUTATED_DURING_RUN")
    known = {**runtime, **system_libraries}
    used_core = {p for p in observer.opened if is_tooling_file(Path(p))}
    for p in used_core:
        need(p in runtime, "UNBOUND_OPENED_CORE_TOOLING", p)
    for rel in ("Lean.olean", "Lean/Compiler/ModPkgExt.olean", "Lake/Build/Trace.olean"):
        p = str((prefix / "lib/lean" / rel).resolve(strict=True))
        need(p in used_core, "EXPECTED_CORE_IMPORT_NOT_OBSERVED", rel)
    loader_files = sorted(logs.glob("loader.*"))
    need(bool(loader_files), "DYNAMIC_LOADER_LOG_NOT_PRODUCED")
    loaded_libraries = {p for p in mapped_files if ".so" in Path(p).name}
    for log in loader_files:
        for line in log.read_text(errors="strict").splitlines():
            match = re.search(r"calling init:\s*(/\S+)", line) or re.search(r"calling fini:\s*(/\S+)", line)
            if match:
                loaded_libraries.add(str(Path(match.group(1)).resolve(strict=True)))
    need(any("libleanshared" in Path(p).name for p in loaded_libraries), "LEAN_SHARED_LIBRARY_NOT_OBSERVED")
    need(any("libc.so" in Path(p).name for p in loaded_libraries), "SYSTEM_C_LIBRARY_NOT_OBSERVED")
    for p in loaded_libraries:
        need(p in known, "UNBOUND_ACTUALLY_LOADED_LIBRARY", p)
        need(fingerprint(Path(p)) == known[p], "LOADED_LIBRARY_CHANGED", p)
    observation = {"core_open_observer": "inotify superset; child-specific process maps retained separately",
                   "core_open_count": len(used_core), "core_open_files": {p: runtime[p] for p in sorted(used_core)},
                   "actual_loaded_libraries": {p: known[p] for p in sorted(loaded_libraries)}}
    write_json(logs / "actual-runtime-inputs.json", observation)
    return result


def verify_candidate(pair: dict, directory: Path, logs: Path) -> dict:
    stems = ["roundtrip.current", "roundtrip.accepted", "template.none.nonpackage", "template.some.nonpackage",
             "package.expected-none", "package.expected-some", "package.current", "package.accepted",
             "normalized.current", "normalized.accepted"]
    expected = {stem + ".olean" for stem in stems} | {"input.current.olean", "input.accepted.olean", "input.current.trace", "candidate.json"}
    need({p.name for p in directory.iterdir()} == expected, "UNEXPECTED_GENERATED_FILE_SET", pair["module"])
    need(all(p.is_file() and not p.is_symlink() for p in directory.iterdir()), "INVALID_GENERATED_FILE_TYPE")
    candidate = json.loads((directory / "candidate.json").read_bytes())
    need(json.loads((logs / "stdout").read_bytes()) == candidate, "STDOUT_CANDIDATE_MISMATCH")
    need(candidate.get("schema") == "p3_moduledata_package_equivalence_candidate_v1", "CANDIDATE_SCHEMA_MISMATCH")
    need(candidate.get("status") == "DATA_EQUAL_MODULO_VERIFIED_PACKAGE__EXTERNAL_PINS_REQUIRED",
         "CANDIDATE_STATUS_MISMATCH")
    need(candidate.get("module") == pair["module"] and candidate.get("package_extension") == PACKAGE_KEY,
         "CANDIDATE_MODULE_OR_PACKAGE_MISMATCH")
    need(candidate.get("current_package") == "some imbalancedChen" and candidate.get("accepted_package") == "none",
         "CANDIDATE_PACKAGE_VALUES_MISMATCH")
    for key in ("original_byte_roundtrips_equal", "all_moduledata_except_verified_package_byte_equal",
                "trace_output_matches_direct_current_lake_hash"):
        need(candidate.get(key) is True, "CANDIDATE_GATE_NOT_TRUE", key)
    need(candidate.get("isModule") is False, "CANDIDATE_MULTIPART_FLAG")
    need(candidate.get("extension_names", []).count(PACKAGE_KEY) == 1, "CANDIDATE_PACKAGE_NAME_COUNT")
    generated = {p.name: fingerprint(p) for p in sorted(directory.iterdir())}
    checks = []
    for key, label, snapshot in (("current", "current", "input.current.olean"),
                                 ("accepted", "accepted", "input.accepted.olean"),
                                 ("real_trace", "trace", "input.current.trace")):
        pin = pair[key]
        need(generated[snapshot]["sha256"] == pin["sha256"] and generated[snapshot]["bytes"] == pin["bytes"],
             "SNAPSHOT_PIN_MISMATCH", snapshot)
        input_info = candidate["input_" + label]
        snapshot_info = candidate["snapshot_" + label]
        need(input_info["path"] == pin["path"] and input_info["bytes"] == pin["bytes"], "CANDIDATE_INPUT_BINDING_MISMATCH")
        need(snapshot_info["path"] == str(directory / snapshot) and snapshot_info["bytes"] == pin["bytes"],
             "CANDIDATE_SNAPSHOT_BINDING_MISMATCH")
        need(snapshot_info["lake_hash_actual_bytes"] == input_info["lake_hash_actual_bytes"],
             "CANDIDATE_SNAPSHOT_LAKE_HASH_MISMATCH")
        checks.append((Path(pin["path"]), directory / snapshot, "original_snapshot_" + label))
    artifact_paths = [item["path"] for item in candidate["artifacts"]]
    need(artifact_paths == [str(directory / (stem + ".olean")) for stem in stems], "CANDIDATE_ARTIFACT_PATHS_MISMATCH")
    for item in candidate["artifacts"]:
        file = generated[Path(item["path"]).name]
        need(item["bytes"] == file["bytes"] and re.fullmatch(r"[0-9a-f]{16}", item["lake_hash_actual_bytes"]) is not None,
             "CANDIDATE_ARTIFACT_METADATA_MISMATCH")
    trace = json.loads((directory / "input.current.trace").read_bytes())
    direct_lake_hash = candidate["input_current"]["lake_hash_actual_bytes"]
    need(trace["outputs"]["o"] == [direct_lake_hash + ".olean"], "ACTUAL_BYTE_LAKE_HASH_TRACE_MISMATCH")
    checks.extend([
        (directory / "input.current.olean", directory / "roundtrip.current.olean", "current_roundtrip"),
        (directory / "input.accepted.olean", directory / "roundtrip.accepted.olean", "accepted_roundtrip"),
        (directory / "normalized.current.olean", directory / "normalized.accepted.olean", "complete_normalized_moduledata"),
        (directory / "package.current.olean", directory / "package.expected-some.olean", "typed_current_some_payload"),
        (directory / "package.accepted.olean", directory / "package.expected-none.olean", "typed_accepted_none_payload"),
        (directory / "template.none.nonpackage.olean", directory / "template.some.nonpackage.olean", "template_nonpackage_fields"),
    ])
    comparisons = {}
    for left, right, label in checks:
        comparisons[label] = bytes_equal(left, right)
        need(comparisons[label], "INDEPENDENT_BYTE_COMPARISON_FAILED", label)
    comparisons["typed_some_none_are_distinct"] = not bytes_equal(directory / "package.expected-some.olean", directory / "package.expected-none.olean")
    need(comparisons["typed_some_none_are_distinct"], "TYPED_PACKAGE_TEMPLATES_NOT_DISTINCT")
    return {"module": pair["module"], "status": "COMPLETE_MODULEDATA_EQUAL_EXCEPT_VERIFIED_PACKAGE_PAYLOAD",
            "pins": pair, "generated_files": generated, "independent_byte_comparisons": comparisons,
            "direct_current_lake_hash": direct_lake_hash, "real_trace": trace,
            "normalized_sha256": generated["normalized.current.olean"]["sha256"],
            "candidate_sha256": generated["candidate.json"]["sha256"],
            "extension_order_gate": "The exact reviewed witness requires identical full extension-name arrays before normalization.",
            "scope": "New computational data-binding evidence only; no native ABI equivalence, imported-object identity, kernel replay, cache adoption or new proof acceptance."}


def evidence_inventory(root: Path) -> dict:
    return {str(p.relative_to(root)): fingerprint(p) for p in sorted(root.rglob("*"))
            if p.is_file() and p.name not in {"final-receipt.json", "evidence-inventory.json"}}


def main() -> int:
    global OUTPUT_ROOT
    os.umask(0o077)
    summary = {"schema": "p3_moduledata_equivalence_execution_v1", "started_at": utc_now(),
               "status": "IN_PROGRESS", "pairs_completed": [], "cache_adopted": False,
               "kernel_replayed": False, "proof_credit_added": False,
               "script_sha256": SCRIPT_SHA256, "review_sha256": REVIEW_SHA256, "reuse_sha256": REUSE_SHA256}
    stage, module = "initialization", None
    before_sources = before_inputs = before_native = runtime_before = libraries_before = None
    prefix = review = reuse = None
    verified_generated = {}
    failure = None
    try:
        need(PROJECT.resolve(strict=True) == PROJECT, "PROJECT_ROOT_IS_SYMLINK")
        if not EVIDENCE_PARENT.exists():
            EVIDENCE_PARENT.mkdir(mode=0o700)
        need(EVIDENCE_PARENT.is_dir() and EVIDENCE_PARENT.resolve(strict=True) == EVIDENCE_PARENT,
             "EVIDENCE_PARENT_IS_NOT_LITERAL_EXTERNAL_DIRECTORY")
        need(not EVIDENCE_PARENT.is_relative_to(PROJECT), "EVIDENCE_PARENT_INSIDE_PROJECT")
        need(not any((EVIDENCE_PARENT / name).exists() for name in (".git", ".lake", "lakefile.toml", "lakefile.lean")),
             "EVIDENCE_PARENT_LOOKS_LIKE_PROJECT")
        OUTPUT_ROOT = Path(tempfile.mkdtemp(prefix="p3-moduledata-", dir=EVIDENCE_PARENT))
        need(OUTPUT_ROOT.resolve(strict=True).parent == EVIDENCE_PARENT, "FRESH_DIRECTORY_ESCAPED_PARENT")
        summary["evidence_root"] = str(OUTPUT_ROOT)
        private_mkdir(OUTPUT_ROOT / "runtime")
        private_mkdir(OUTPUT_ROOT / "logs")
        private_mkdir(OUTPUT_ROOT / "tmp")
        script_raw, review_raw, reuse_raw, review, reuse = load_embedded()
        script = OUTPUT_ROOT / "P3ModuleDataEquivalence.lean"
        write_new(script, script_raw)
        write_new(OUTPUT_ROOT / "review.json", review_raw)
        write_new(OUTPUT_ROOT / "immutable-reuse.json", reuse_raw)
        wrapper_path = Path(__file__).resolve(strict=True)
        summary["wrapper"] = fingerprint(wrapper_path)
        require_pin(script, review["script"])
        stage = "pinned_inputs"
        before_sources = source_state(reuse)
        before_inputs = {pair["module"]: pair_input_state(pair) for pair in review["pairs"]}
        before_native = {name: native_bundle(name) for name in ALLOWED_MODULES}
        write_json(OUTPUT_ROOT / "source-and-config-before.json", before_sources)
        write_json(OUTPUT_ROOT / "five-inputs-before.json", before_inputs)
        write_json(OUTPUT_ROOT / "native-bundles-before.json", before_native)
        write_new(OUTPUT_ROOT / "baseline-acceptance-receipt.json", BASELINE_RECEIPT.read_bytes())
        require_pin(OUTPUT_ROOT / "baseline-acceptance-receipt.json", reuse["acceptance_receipts"]["baseline"]["git"])
        metadata = long_slot_metadata()
        write_json(OUTPUT_ROOT / "long-slot-readonly-metadata.json", metadata)
        emit({"event": "readonly_metadata", "module": LONG_SLOT_MODULE,
              "current_olean_sha256": metadata["current"][".olean"].get("sha256"),
              "current_trace_sha256": metadata["current"][".trace"].get("sha256"),
              "private_sha256": metadata["current"][".olean.private"].get("sha256"),
              "server_sha256": metadata["current"][".olean.server"].get("sha256"),
              "accepted_overlay_sha256": metadata["accepted_overlay"].get("sha256"),
              "equivalence_check_requested": False})
        stage = "runtime_fingerprints"
        summary["lean_executable"] = require_pin(LEAN, review["lean_binary"])
        prefix = LEAN.resolve(strict=True).parent.parent
        env = clean_environment(OUTPUT_ROOT / "tmp")
        runtime_started = time.monotonic()
        runtime_before = tooling_fingerprints(prefix)
        libraries_before = library_dependencies(prefix, runtime_before, env, OUTPUT_ROOT / "runtime")
        write_json(OUTPUT_ROOT / "runtime" / "tooling-before.json", runtime_before)
        write_json(OUTPUT_ROOT / "runtime" / "system-libraries-before.json", libraries_before)
        summary["runtime_fingerprint_scope"] = {"prefix": str(prefix), "core_file_count": len(runtime_before),
            "core_bytes_hashed": sum(p["bytes"] for p in runtime_before.values()),
            "system_library_count": len(libraries_before),
            "system_library_bytes_hashed": sum(p["bytes"] for p in libraries_before.values()),
            "before_seconds": time.monotonic() - runtime_started}
        emit({"event": "runtime_bound", "lean_sha256": summary["lean_executable"]["sha256"],
              "core_files": len(runtime_before), "core_bytes": summary["runtime_fingerprint_scope"]["core_bytes_hashed"],
              "seconds": round(summary["runtime_fingerprint_scope"]["before_seconds"], 3),
              "script_sha256": SCRIPT_SHA256, "source_count": 77})
        for index, pair in enumerate(review["pairs"]):
            module = pair["module"]
            stage = "pair_before"
            need(pair_input_state(pair) == before_inputs[module], "PAIR_INPUTS_CHANGED_BEFORE_RUN", module)
            need(native_bundle(module) == before_native[module], "NATIVE_BUNDLE_CHANGED_BEFORE_RUN", module)
            evidence = OUTPUT_ROOT / f"pair-{index + 1:02d}-{module.split('.')[-1]}"
            logs = OUTPUT_ROOT / "logs" / f"pair-{index + 1:02d}"
            private_mkdir(logs)
            stage = "standalone_witness"
            run = run_witness(pair, script, evidence, logs, prefix, env, runtime_before, libraries_before)
            stage = "independent_generated_bytes"
            result = verify_candidate(pair, evidence, logs)
            stage = "pair_after"
            after = pair_input_state(pair)
            need(after == before_inputs[module], "PAIR_INPUTS_CHANGED_AFTER_RUN", module)
            need(native_bundle(module) == before_native[module], "NATIVE_BUNDLE_CHANGED_AFTER_RUN", module)
            result["input_fingerprints_after"] = after
            result["run"] = run
            write_json(OUTPUT_ROOT / f"pair-{index + 1:02d}-binding.json", result)
            verified_generated.update({item["path"]: item for item in result["generated_files"].values()})
            summary["pairs_completed"].append({"module": module, "normalized_sha256": result["normalized_sha256"],
                                                "candidate_sha256": result["candidate_sha256"]})
            emit({"event": "pair", "module": module, "status": "DATA_EQUIVALENT_MODULO_VERIFIED_PACKAGE",
                  "current_sha256": pair["current"]["sha256"], "accepted_sha256": pair["accepted"]["sha256"],
                  "trace_sha256": pair["real_trace"]["sha256"], "normalized_sha256": result["normalized_sha256"],
                  "candidate_sha256": result["candidate_sha256"]})
        need(len(summary["pairs_completed"]) == 5, "NOT_ALL_FIVE_PAIRS_COMPLETED")
        stage, module = "final_readonly_guards", None
    except BaseException as exc:
        failure = {"stage": stage, "module": module,
                   "code": exc.code if isinstance(exc, Hold) else type(exc).__name__,
                   "detail": str(exc), "traceback": traceback.format_exc()}
    finally:
        if OUTPUT_ROOT is not None:
            guard_errors = []
            try:
                require_pin(OUTPUT_ROOT / "P3ModuleDataEquivalence.lean", {"sha256": SCRIPT_SHA256})
                require_pin(OUTPUT_ROOT / "review.json", {"sha256": REVIEW_SHA256})
                require_pin(OUTPUT_ROOT / "immutable-reuse.json", {"sha256": REUSE_SHA256})
                if "wrapper" in summary:
                    need(fingerprint(Path(summary["wrapper"]["path"])) == summary["wrapper"],
                         "WRAPPER_CHANGED_DURING_RUN")
                for path, before in verified_generated.items():
                    need(fingerprint(Path(path)) == before, "VERIFIED_GENERATED_EVIDENCE_CHANGED", path)
            except BaseException as exc:
                guard_errors.append({"gate": "exact_witness_manifests_and_generated_evidence", "detail": str(exc)})
            if reuse is not None and before_sources is not None:
                try:
                    after_sources = source_state(reuse)
                    write_json(OUTPUT_ROOT / "source-and-config-after.json", after_sources)
                    need(after_sources == before_sources, "SOURCE_CONFIGURATION_OR_RECEIPT_CHANGED")
                except BaseException as exc:
                    guard_errors.append({"gate": "source_configuration_receipt", "detail": str(exc)})
            if review is not None and before_inputs is not None:
                try:
                    after_inputs = {pair["module"]: pair_input_state(pair) for pair in review["pairs"]}
                    write_json(OUTPUT_ROOT / "five-inputs-after.json", after_inputs)
                    need(after_inputs == before_inputs, "FIVE_PAIR_INPUTS_CHANGED")
                    after_native = {name: native_bundle(name) for name in ALLOWED_MODULES}
                    write_json(OUTPUT_ROOT / "native-bundles-after.json", after_native)
                    need(after_native == before_native, "NATIVE_BUNDLES_CHANGED")
                except BaseException as exc:
                    guard_errors.append({"gate": "five_pairs_native_parts", "detail": str(exc)})
            if prefix is not None and runtime_before is not None:
                try:
                    runtime_started = time.monotonic()
                    after_runtime = tooling_fingerprints(prefix)
                    write_json(OUTPUT_ROOT / "runtime" / "tooling-after.json", after_runtime)
                    need(after_runtime == runtime_before, "CORE_TOOLING_CHANGED")
                    if libraries_before is not None:
                        after_libs = {p: fingerprint(Path(p)) for p in libraries_before}
                        write_json(OUTPUT_ROOT / "runtime" / "system-libraries-after.json", after_libs)
                        need(after_libs == libraries_before, "SYSTEM_SHARED_LIBRARIES_CHANGED")
                    need(fingerprint(LEAN) == summary["lean_executable"], "LEAN_EXECUTABLE_CHANGED")
                    summary["runtime_after_seconds"] = time.monotonic() - runtime_started
                except BaseException as exc:
                    guard_errors.append({"gate": "runtime", "detail": str(exc)})
            if guard_errors:
                summary["final_guard_failures"] = guard_errors
                if failure is None:
                    failure = {"stage": "final_readonly_guards", "module": None, "code": "READONLY_GUARD_FAILED"}
            if failure is not None:
                write_json(OUTPUT_ROOT / "failure.json", failure)
            summary["status"] = "HOLD_FIRST_DISCREPANCY" if failure else "FIVE_PAIRS_BOUND_COMPLETE_MODULEDATA_MODULO_VERIFIED_PACKAGE"
            summary["ended_at"] = utc_now()
            summary["scope"] = "Successful final status binds all 77 source pins, three configuration files, the old baseline receipt, five exact current/accepted/trace pins, and the recorded runtime. HOLD does not attest a completed binding. This is standalone data evidence only; imported-object compatibility, native ABI equivalence, existing normal API/guard checks, kernel replay, owner acceptance and cache adoption are not supplied or bypassed."
            inventory = evidence_inventory(OUTPUT_ROOT)
            write_json(OUTPUT_ROOT / "evidence-inventory.json", inventory)
            summary["evidence_inventory"] = fingerprint(OUTPUT_ROOT / "evidence-inventory.json")
            write_json(OUTPUT_ROOT / "final-receipt.json", summary)
            receipt = fingerprint(OUTPUT_ROOT / "final-receipt.json")
            emit({"event": "final", "status": summary["status"], "pairs_completed": len(summary["pairs_completed"]),
                  "evidence_root": str(OUTPUT_ROOT), "receipt_sha256": receipt["sha256"],
                  "inventory_sha256": summary["evidence_inventory"]["sha256"],
                  "failure_code": failure.get("code") if failure else None})
        else:
            emit({"event": "final", "status": "HOLD_BEFORE_EVIDENCE_DIRECTORY", "pairs_completed": 0,
                  "failure_code": failure.get("code") if failure else "UNKNOWN_INITIALIZATION_FAILURE"})
    return 1 if failure else 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as fatal:
        # Even evidence-finalization failures must not spill a traceback or
        # private declaration/trace contents into the MCP stdout/stderr stream.
        print(json.dumps({"event": "final", "status": "HOLD_EVIDENCE_FINALIZATION_FAILED",
                          "failure_code": type(fatal).__name__,
                          "evidence_root": str(OUTPUT_ROOT) if OUTPUT_ROOT else None},
                         sort_keys=True), flush=True)
        raise SystemExit(1)
